$('piano').onpointerdown=e=>{if(e.button!==0||!pattern())return;const p=pianoPoint(e);if(p.x<p.g.label){A.audition(current().instrument,p.g.rows[p.row]).catch(x=>status(x.message));return}if(p.y<24)return;const pat=pattern(),n=[...pat.notes].reverse().find(n=>n.pitch===p.g.rows[p.row]&&p.step>=n.step&&p.step<n.step+n.length),before=C.clone(project);if(n){selectedNote=n.id;drag={before,id:n.id,step:p.step,pitch:n.pitch,original:C.clone(n),resize:p.x>p.g.label+(n.step+n.length)*p.g.unit-8}}else{const note={id:C.id(),step:p.step,pitch:p.g.rows[p.row],length:C.clamp(+$('noteLength').value,.25,p.g.steps-p.step),velocity:.7};pat.notes.push(note);selectedNote=note.id;drag={before,id:note.id,step:p.step,pitch:note.pitch,original:C.clone(note),resize:false};A.audition(current().instrument,note.pitch).catch(()=>{})}$('piano').setPointerCapture(e.pointerId);renderPart();drawPiano();e.preventDefault()};$('piano').onpointermove=e=>{if(!drag)return;const p=pianoPoint(e),n=pattern()?.notes.find(n=>n.id===drag.id);if(!n)return;if(drag.resize)n.length=C.clamp(p.step-drag.original.step+1,.25,p.g.steps-drag.original.step);else{n.step=C.clamp(drag.original.step+p.step-drag.step,0,p.g.steps-n.length);n.pitch=p.g.rows[p.row]}drawPiano()};$('piano').onpointerup=()=>{if(!drag)return;remember(drag.before);drag=null;if(A.playing){A.update(project).catch(e=>status(e.message));$('queueStatus').hidden=false;$('queueStatus').textContent='Note edit queued · next bar'}render()};$('piano').onpointercancel=()=>{if(!drag)return;project=drag.before;drag=null;render()};$('piano').oncontextmenu=e=>{e.preventDefault();const p=pianoPoint(e),n=pattern()?.notes.find(n=>n.pitch===p.g.rows[p.row]&&p.step>=n.step&&p.step<n.step+n.length);if(n)change(()=>{pattern().notes=pattern().notes.filter(x=>x.id!==n.id);selectedNote=null})};

function deleteNote(){if(!selectedNote)return;change(()=>{pattern().notes=pattern().notes.filter(n=>n.id!==selectedNote);selectedNote=null})}

function pause(){$('queueStatus').hidden=true;if(A.playing){playPosition=A.position;A.stop()}updateSummary();$('play').textContent='Play'}

$('play').onclick=async()=>{try{if(A.playing){pause();return}await A.play(project,playPosition);$('play').textContent='Pause';status('Playing your arrangement.')}catch(e){status(e.message)}};$('stop').onclick=()=>{$('queueStatus').hidden=true;A.stop();playPosition=0;updateSummary();$('play').textContent='Play'};let seeking=false,resumeSeek=false;$('seek').onpointerdown=()=>{seeking=true;resumeSeek=A.playing};$('seek').oninput=()=>{const target=+$('seek').value*C.seconds(project);if(!seeking)resumeSeek=A.playing;seeking=true;A.stop();playPosition=Math.min(C.seconds(project)-.01,target);updateSummary()};$('seek').onchange=async()=>{const resume=resumeSeek;seeking=false;resumeSeek=false;if(resume){await A.play(project,playPosition);$('play').textContent='Pause'}else $('play').textContent='Play'};document.addEventListener('musictransport',()=>{if(!A.playing)$('queueStatus').hidden=true;updateSummary();$('play').textContent=A.playing?'Pause':'Play';const head=$('playhead');head.hidden=!A.playing;if(A.playing){head.style.left=(184+A.position/C.seconds(project)*(project.sections.reduce((a,s)=>a+Math.max(118,s.bars*32)+7,0)))+'px'}});

$('mood').innerHTML=Object.entries(C.moods).map(([k,m])=>'<option value="'+k+'">'+m.name+'</option>').join('');$('key').innerHTML=C.keys.map((k,i)=>'<option value="'+i+'">'+k+'</option>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('mood').onchange=()=>{const running=A.playing;change(()=>{const k=$('mood').value,m=C.moods[k];project.mood=k;if(!running)project.tempo=m.tempo;project.scale=m.scale;project.room=m.space;for(const t of project.tracks){if(t.locked||t.sound||t.audio)continue;t.instrument=({melody:m.lead,harmony:m.bed,bass:m.bass,texture:m.arp,rhythm:'drums'})[t.role]||t.instrument}if(running){project=C.generate({},project);status('New direction queued for the next bar · pace and locked parts retained.')}},{keepPlaying:running,liveArrangement:running})};document.addEventListener('musicdirection',()=>{$('queueStatus').hidden=true;status('Queued changes are now playing.')});for(const k of ['tempo','energy','busyness','human','master','room'])slider($(k),v=>{if(k==='tempo'&&C.totalBars(project)*240/v>180){$(k).value=project.tempo;status('Shorten the arrangement before lowering the pace further.');return}project[k]=v;if(k==='master')A.master(v)},{live:k!=='tempo',commit:()=>{if(k==='room'&&A.playing){A.update(project);$('queueStatus').hidden=false;$('queueStatus').textContent='Room queued · next bar'}}});$('key').onchange=()=>change(()=>project.key=+$('key').value,{keepPlaying:true});$('scale').onchange=()=>change(()=>project.scale=$('scale').value,{keepPlaying:true});$('seed').onchange=()=>change(()=>project.seed=$('seed').value.trim()||'jago',{keepPlaying:true});$('newSeed').onclick=()=>change(()=>project.seed=crypto.getRandomValues(new Uint32Array(1))[0].toString(36),{keepPlaying:true});$('generate').onclick=()=>change(()=>{if(!project.tracks.some(t=>!t.sound&&!t.audio)){const fresh=C.generate({mood:project.mood,seed:project.seed});const additions=fresh.tracks.slice(0,Math.max(0,12-project.tracks.length));additions.forEach((t,i)=>{t.id='generated-'+i;while(project.tracks.some(x=>x.id===t.id))t.id+='x';t.patterns={};t.enabled={}});project.tracks.push(...additions);if(project.name==='Untitled session')project.name=C.moods[project.mood].name}project=C.generate({},project);selectedNote=null;status(A.playing?'New notes queued for the next bar.':'New notes generated. Locked parts stayed intact.')},{keepPlaying:A.playing,liveArrangement:A.playing});$('projectName').onchange=()=>change(()=>project.name=$('projectName').value.trim()||'Untitled session',{keepPlaying:true});$('loop').onchange=()=>change(()=>project.loop=$('loop').checked,{keepPlaying:A.playing,liveArrangement:A.playing});$('sessionNotes').onchange=()=>change(()=>project.notes=$('sessionNotes').value.slice(0,10000));$('undo').onclick=undo;$('redo').onclick=redo;$('deleteNote').onclick=deleteNote;$('gridZoom').oninput=drawPiano;$('patternBars').onchange=()=>change(()=>{const pat=pattern();if(!pat)return;pat.bars=+$('patternBars').value;status(pat.notes.filter(n=>n.step>=pat.bars*16).length+' notes stored beyond the current pattern length. Expand to reveal them.')});$('patternClear').onclick=()=>{if(pattern())change(()=>{pattern().notes=[];selectedNote=null})};$('patternVary').onclick=()=>{const t=current(),s=currentSection();if(!t||t.locked)return;if(t.sound||t.audio)return status('Edit the sound recipe or move its cues manually.');change(()=>{t.variation=(t.variation||0)+1;t.patterns[s.id]=C.generatePattern(project,t,s,t.variation);selectedNote=null},{keepPlaying:A.playing,liveArrangement:A.playing})};$('patternAudition').onclick=async()=>{try{const t=current();if(!t)return;const p=C.clone(project);p.tracks.forEach(x=>{x.solo=x.id===t.id;x.muted=false});await A.play(p,playPosition);$('play').textContent='Pause';status('Hearing only '+t.name+'. Stop to return to the complete arrangement.')}catch(e){status(e.message)}};

$('addTrack').onclick=()=>{if(project.tracks.length>=12)return status('Up to 12 parts in this version.');dialog('Add a musical part','<label>Name<input id="newPartName" value="My melody"></label><label>Instrument<select id="newPartVoice">'+Object.entries(C.voices).map(([k,v])=>'<option value="'+k+'">'+v.name+'</option>').join('')+'</select></label><p class="hint">Or start with an editable sound recipe or your own recording.</p><div class="row"><button id="partSoundRoute">Sound workshop</button><button id="partImportRoute">Import audio</button></div><button id="newPartAdd" class="primary">Add blank part</button><p class="hint">Draw notes manually, or choose Vary notes to create a compatible idea.</p>');$('partSoundRoute').onclick=()=>{closeDialog();showView('sounds')};$('partImportRoute').onclick=()=>{closeDialog();$('audioFile').click()};$('newPartAdd').onclick=()=>{change(()=>{const voice=$('newPartVoice').value,t=C.makeTrack(voice==='drums'?'rhythm':'melody',voice,$('newPartName').value||'Part');for(const s of project.sections){t.patterns[s.id]={bars:4,notes:[]};t.enabled[s.id]=true}project.tracks.push(t);selected=t.id;selectedNote=null});closeDialog()}};$('addSection').onclick=()=>{if(project.sections.length>=12||C.seconds(project)+4*240/project.tempo>180)return status('Section or duration limit reached.');change(()=>{const s={id:C.id(),name:'New section',bars:4,energy:1};project.sections.push(s);for(const t of project.tracks){t.patterns[s.id]={bars:4,notes:[]};t.enabled[s.id]=true}sectionSelected=s.id})};

$('theme').onchange=()=>{document.documentElement.dataset.theme=$('theme').value;localStorage.setItem('jago-music-theme',$('theme').value);drawPiano();if(soundBuffer)waveform(soundBuffer)};

function renderSound(){const editing=project.tracks.find(t=>t.id===editingSoundTrack);$('soundApply').hidden=!editing;$('soundApply').textContent=editing?'Update '+editing.name:'Update selected part';if(project.workshop)soundRecipe=project.workshop;const s=soundRecipe,definition=C.soundTypes[s.type];$('soundTitle').textContent=s.label||(s.type==='door'?(s.action==='open'?'Door opening':s.action==='both'?'Door open & close':definition.name):definition.name);$('soundGroup').textContent=definition.group;$('soundDescription').textContent=s.loop?'A repeating sound bed or sequence. Tune its character and length, then use it beneath music or in a scene.':'A distinct cue. Shape its weight, colour and duration, then export or place it in your track.';renderSoundTypes();$('soundSettings').innerHTML=(['footsteps','door'].includes(s.type)?'<label>'+ (s.type==='door'?'Door construction':'Walking surface')+'<select id="soundSurface">'+(s.type==='door'?['wood','metal']:['stone','wood','gravel','grass','metal']).map(k=>'<option value="'+k+'">'+k.charAt(0).toUpperCase()+k.slice(1)+'</option>').join('')+'</select></label>':'')+(s.type==='door'?'<label>Door action<select id="soundAction"><option value="both">Open then close</option><option value="open">Opening only</option><option value="close">Closing only</option></select></label>':'')+'<label>Seed<div class="seed-row"><input id="soundSeed" maxlength="100" value="'+esc(s.seed)+'"><button id="soundSeedButton">Shuffle</button></div></label><label>Length · seconds<input id="soundDuration" type="number" min=".1" max="30" step=".1" value="'+s.duration+'"></label><label class="inline"><input id="soundLoop" type="checkbox" '+(s.loop?'checked':'')+'> Repeat as a loop</label><label class="inline"><input id="soundNormalize" type="checkbox" '+(s.normalize!==false?'checked':'')+'> Match useful sound levels</label>'+[['size',s.type==='footsteps'?'Light ↔ heavy contact':'Small ↔ weighty'],['tone','Dark ↔ bright'],['texture',s.type==='door'?'Clean ↔ creaky movement':'Smooth ↔ rough'],...(['Nature','Ambience','Sequences'].includes(definition.group)?[['rate','Slow ↔ active']]:[]),...(s.type==='footsteps'?[['variation','Step variation']]:[]),...(['clang','shield'].includes(s.type)?[['resonance','Short contact ↔ ringing metal']]:[]),['distance','Close ↔ distant'],['space','Dry ↔ spacious'],['volume','Sound level']].map(([k,name])=>'<label>'+name+'<input data-sound-control="'+k+'" type="range" min="0" max="1" step=".01" value="'+(s[k]??(k==='resonance'?.5:0))+'"></label>').join('');if($('soundSurface')){$('soundSurface').value=s.surface||'wood';$('soundSurface').onchange=()=>soundChange(()=>s.surface=$('soundSurface').value)}if($('soundAction')){$('soundAction').value=s.action||'both';$('soundAction').onchange=()=>soundChange(()=>{s.action=$('soundAction').value;delete s.label})}$('soundSeed').onchange=()=>soundChange(()=>s.seed=$('soundSeed').value.trim()||'jago');$('soundSeedButton').onclick=()=>soundChange(()=>s.seed=crypto.getRandomValues(new Uint32Array(1))[0].toString(36));$('soundDuration').onchange=()=>soundChange(()=>s.duration=C.clamp(+$('soundDuration').value,.1,30));$('soundLoop').onchange=()=>soundChange(()=>s.loop=$('soundLoop').checked);$('soundNormalize').onchange=()=>soundChange(()=>s.normalize=$('soundNormalize').checked);document.querySelectorAll('[data-sound-control]').forEach(el=>slider(el,v=>{s[el.dataset.soundControl]=v;soundBuffer=null;soundToken++;queueSoundPreview()},{live:true}));if(soundBuffer)waveform(soundBuffer)}

function renderSoundTypes(){const q=$('soundSearch').value.toLowerCase();$('soundTypes').innerHTML=Object.entries(C.soundTypes).filter(([key])=>key!=='crowd').filter(([k])=>k!=='custom'&&k!=='crowd').filter(([k,v])=>(v.name+' '+v.group).toLowerCase().includes(q)).map(([k,v])=>'<button data-sound-type="'+k+'" aria-pressed="'+(k===soundRecipe.type)+'">'+v.name+'<small>'+v.group+' · '+(v.loop?'Ambience / sequence':'Sound cue')+'</small></button>').join('');document.querySelectorAll('[data-sound-type]').forEach(b=>b.onclick=()=>soundChange(()=>{editingSoundTrack=null;soundRecipe=C.sound(b.dataset.soundType,soundRecipe.seed);project.workshop=soundRecipe}))}

function soundChange(fn){const listening=A.soundPlaying;soundToken++;soundBuffer=null;change(()=>{fn();project.workshop=soundRecipe},{keepPlaying:listening||A.playing});renderSound();if(listening)queueSoundPreview();$('soundMetrics').textContent='Changed recipe · listen to hear this variation.'}

function waveform(b){const c=$('soundWave'),ctx=c.getContext('2d'),theme=getComputedStyle(document.documentElement),w=c.width,h=c.height,d=b.getChannelData(0);ctx.fillStyle=theme.getPropertyValue('--stage');ctx.fillRect(0,0,w,h);ctx.strokeStyle=theme.getPropertyValue('--line');ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.fillStyle=theme.getPropertyValue('--accent');for(let x=0;x<w;x++){const from=Math.floor(x/w*d.length),to=Math.max(from+1,Math.floor((x+1)/w*d.length));let min=0,max=0;for(let i=from;i<to;i++){min=Math.min(min,d[i]);max=Math.max(max,d[i])}ctx.fillRect(x,h/2-max*h*.8,1,Math.max(1,(max-min)*h*.8))}const m=A.metrics(b);$('soundMetrics').textContent=m.seconds.toFixed(1)+' seconds · '+b.sampleRate.toLocaleString()+' Hz · peak '+(20*Math.log10(Math.max(m.peak,.00001))).toFixed(1)+' dBFS · '+(soundRecipe.loop?'Loop':'Cue')}

$('soundSearch').oninput=renderSoundTypes;$('soundPlay').onclick=async()=>{const token=++soundToken;$('soundPlay').disabled=true;status('Preparing your sound…');try{const b=await A.previewSound(C.clone(soundRecipe),{repeat:soundRecipe.loop});if(token===soundToken&&b){soundBuffer=b;waveform(b);status('Listening · '+C.soundTypes[soundRecipe.type].name)}}catch(e){status(e.message)}finally{$('soundPlay').disabled=false}};$('soundStop').onclick=()=>{soundToken++;A.stop();status('Sound stopped.')};$('soundShuffle').onclick=()=>soundChange(()=>{soundRecipe.seed=crypto.getRandomValues(new Uint32Array(1))[0].toString(36);const r=C.random(soundRecipe.seed);for(const k of ['size','tone','texture','rate'])soundRecipe[k]=.2+r()*.6});$('soundSave').onclick=()=>{dialog('Keep this sound','<label>Name<input id="savedSoundName" maxlength="80" value="'+esc(C.soundTypes[soundRecipe.type].name)+'"></label><label class="inline"><input id="savedSoundFavourite" type="checkbox" checked> Favourite</label><button id="confirmSaveSound" class="primary">Save recipe</button>');$('confirmSaveSound').onclick=()=>{if(project.library.length>=100)return status('This project can hold 100 sound recipes.');change(()=>project.library.push({id:C.id(),name:$('savedSoundName').value.trim()||'My sound',favourite:$('savedSoundFavourite').checked,folder:$('saveSoundFolder')?.value||'',recipe:C.clone(soundRecipe)}));closeDialog();status('Sound saved to My sounds. It stays editable.')}};

function addSound(s,name){if(project.tracks.length>=12)return status('Up to 12 parts in this version.');dialog('Place your sound','<label>Part name<input id="soundPartName" maxlength="80" value="'+esc(name)+'"></label><label>Where?<select id="soundSection">'+project.sections.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')+'<option value="all">Every section</option></select></label><button id="confirmAddSound" class="primary">Add editable sound part</button><p class="hint">One cue starts each chosen section. Draw more cues or change their length in the note grid.</p>');$('soundSection').value=sectionSelected;$('confirmAddSound').onclick=()=>{change(()=>{const t=C.makeTrack('sound','pad',$('soundPartName').value||name),where=$('soundSection').value;t.sound=C.clone(s);t.locked=true;t.space=s.space;for(const section of project.sections){t.enabled[section.id]=where==='all'||where===section.id;t.patterns[section.id]={bars:4,notes:[{id:'sound-cue',step:0,pitch:60,length:Math.min(64,s.duration/(60/project.tempo/4)),velocity:.8}]}}project.tracks.push(t);selected=t.id;selectedNote=null});closeDialog();showView('music');status('Sound added as an editable part.')}}

$('soundAdd').onclick=()=>addSound(soundRecipe,soundRecipe.label||C.soundTypes[soundRecipe.type].name);$('soundExport').onclick=async()=>{const s=C.clone(soundRecipe);try{status('Rendering sound WAV…');const b=await A.renderSound(s);F.save(A.wav(b),F.safe(s.label||s.characterName||C.soundTypes[s.type].name)+'-'+s.seed+'.wav');F.save(new Blob([JSON.stringify({format:'jagosound',version:1,recipe:s},null,2)],{type:'application/json'}),F.safe(s.label||s.characterName||C.soundTypes[s.type].name)+'.jagosound');status('WAV and editable sound recipe exported.')}catch(e){status(e.message)}};

function renderLibrary(){const q=$('librarySearch').value.toLowerCase(),items=[...($('showBuiltins').checked?C.defaults():[]),...project.library].filter(l=>(!$('favouritesOnly').checked||l.favourite)&&(l.name+' '+C.soundTypes[l.recipe.type].name).toLowerCase().includes(q)&&(!$('soundFolderFilter')||$('soundFolderFilter').value==='*'||$('soundFolderFilter').value==='_unfiled'&&!l.folder||l.folder===$('soundFolderFilter').value||l.folder?.startsWith($('soundFolderFilter').value+'/')));$('soundLibrary').innerHTML=items.length?items.map(l=>'<article class="sound-card"><div class="eyebrow">'+esc(C.soundTypes[l.recipe.type].group)+'</div><h3>'+esc(l.name)+'</h3><p>'+l.recipe.duration+' seconds · '+(l.recipe.loop?'Loop':'Cue')+' · '+esc(C.soundTypes[l.recipe.type].name)+'</p><div class="row"><button data-saved-play="'+l.id+'">Listen</button><button data-saved-edit="'+l.id+'">Edit</button><button data-saved-add="'+l.id+'">Add</button><button data-favourite="'+l.id+'" aria-pressed="'+l.favourite+'" title="Toggle favourite">'+(l.favourite?'★':'☆')+'</button>'+(l.builtin?'<span class="hint">Built-in · edit to save your version</span>':'<button data-saved-remove="'+l.id+'">Remove</button>')+'</div></article>').join(''):'<div class="empty">'+(project.library.length?'No matching saved sounds.':'Your shelf is empty. Make a sound, then Save to My sounds to keep its recipe here.')+'</div>';const get=id=>[...project.library,...C.defaults()].find(l=>l.id===id);document.querySelectorAll('[data-saved-play]').forEach(b=>b.onclick=()=>A.previewSound(get(b.dataset.savedPlay).recipe).catch(e=>status(e.message)));document.querySelectorAll('[data-saved-edit]').forEach(b=>b.onclick=()=>{soundChange(()=>soundRecipe=C.clone(get(b.dataset.savedEdit).recipe));showView('sounds')});document.querySelectorAll('[data-saved-add]').forEach(b=>b.onclick=()=>{const l=get(b.dataset.savedAdd);addSound(l.recipe,l.name)});document.querySelectorAll('[data-favourite]').forEach(b=>b.onclick=()=>change(()=>{const l=get(b.dataset.favourite);if(l.builtin){project.library.push({...C.clone(l),id:C.id(),builtin:false,favourite:true})}else l.favourite=!l.favourite}));document.querySelectorAll('[data-saved-remove]').forEach(b=>b.onclick=()=>change(()=>project.library=project.library.filter(l=>l.id!==b.dataset.savedRemove)))}$('showBuiltins').onchange=renderLibrary;$('librarySearch').oninput=renderLibrary;$('favouritesOnly').onchange=renderLibrary;$('libraryCreate').onclick=()=>showView('sounds');$('importAudio').onclick=()=>$('audioFile').click();

$('audioFile').onchange=async()=>{const file=$('audioFile').files[0];$('audioFile').value='';if(!file)return;if(file.size>20000000)return status('Choose an audio file under 20 MB.');if(project.tracks.length>=12)return status('Up to 12 parts.');if(project.tracks.reduce((a,t)=>a+(t.audio?.data.length||0),0)+file.size*1.34>32000000)return status('This project has reached its embedded-audio budget. Use a shorter recording.');try{const bytes=await file.arrayBuffer(),ctx=new AudioContext(),buffer=await ctx.decodeAudioData(bytes.slice(0));await ctx.close();if(buffer.duration>180)throw Error('Import audio up to three minutes long.');if(project.tracks.reduce((n,t)=>n+(t.audio?.duration||0)*44100*8,0)+buffer.duration*44100*8>256000000)throw Error('Decoded audio exceeds this project’s memory budget. Use a shorter recording.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader;reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(new Blob([bytes],{type:file.type?.startsWith('audio/')?file.type:'audio/wav'}))});change(()=>{const t=C.makeTrack('audio','pad',file.name.replace(/\.[^.]+$/,''));t.audio={name:file.name,data,duration:buffer.duration,rights:'User-supplied audio; retain original permissions.'};t.locked=true;for(const s of project.sections){t.enabled[s.id]=s.id===sectionSelected;t.patterns[s.id]={bars:8,notes:[{id:'audio-cue',step:0,pitch:60,length:Math.min(128,buffer.duration/(60/project.tempo/4)),velocity:.8}]}}project.tracks.push(t);selected=t.id});showView('music');status('Audio imported. Use Source trim & fades and place its cues in the grid.')}catch(e){status('Could not import audio: '+e.message)}};

function renderPresets(){$('savedPresets').innerHTML=presets.map((p,i)=>'<button data-direction="'+i+'" class="wide" style="margin-top:6px">'+esc(p.name)+'</button>').join('');document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>{try{const candidate=C.validate(Object.assign(C.clone(project),presets[+b.dataset.direction].settings));change(()=>project=candidate)}catch(e){status(e.message)}})}$('savePreset').onclick=()=>{dialog('Save a direction preset','<label>Name<input id="presetName" maxlength="60" value="'+esc(C.moods[project.mood].name)+'"></label><button id="confirmPreset" class="primary">Save direction</button><p class="hint">Keeps mood, pace, palette, energy, activity, human variation and room. It does not replace your notes.</p>');$('confirmPreset').onclick=()=>{const settings={};for(const k of ['mood','tempo','key','scale','energy','busyness','human','room'])settings[k]=project[k];presets.push({name:$('presetName').value||'Direction',settings});presets=presets.slice(-20);try{localStorage.setItem('jago-music-presets',JSON.stringify(presets))}catch{}renderPresets();closeDialog()}};

function install(p){A.stop();project=C.validate(p);selected=project.tracks[0]?.id;sectionSelected=project.sections[0].id;selectedNote=null;playPosition=0;history=[];future=[];project.workshop=project.workshop||C.sound('rain');soundRecipe=project.workshop;soundBuffer=null;render();showView('music');recovery()}

$('newProject').onclick=()=>{dialog('Start a session','<div class="choice-grid"><button id="startBlank"><strong>Empty session</strong><small>Your own parts, notes and sound cues.</small></button><button id="startGenerated"><strong>Build from a mood</strong><small>Five editable parts and a complete arrangement.</small></button></div><p class="hint">Save this project first if you want a separate backup. Starting a session replaces the current work.</p>');$('startBlank').onclick=()=>{change(()=>{project=C.blank();project.workshop=C.sound('rain');selected=null;sectionSelected=project.sections[0].id;selectedNote=null;playPosition=0});closeDialog()};$('startGenerated').onclick=()=>{change(()=>{project=C.generate({mood:project.mood,seed:project.seed});editingSoundTrack=null;selected=project.tracks[0].id;sectionSelected=project.sections[1].id;selectedNote=null;playPosition=0});closeDialog()}};

$('saveProject').onclick=()=>{const data=JSON.stringify(project,null,2),blob=new Blob([data],{type:'application/json'});const saveUrl=F.save(blob,F.safe(project.name)+'.jagomusic');pendingSaves.set(saveUrl,JSON.stringify(project));if(!window.chrome?.webview){lastSaved=JSON.stringify(project);status('Project download requested. Keep the file as your editable backup.')}else status('Choose where to save your editable session.')};if(window.chrome?.webview)window.chrome.webview.addEventListener('message',e=>{if(e.data.type==='project-save'){if(e.data.ok){lastSaved=pendingSaves.get(e.data.url)||lastSaved;pendingSaves.delete(e.data.url);status('Editable project saved.')}else status('Save cancelled; your project is still open.')}});$('openProject').onclick=()=>$('projectFile').click();async function loadProject(file){if(file.size>40000000)throw Error('Projects must be under 40 MB.');const data=C.validate(JSON.parse(await file.text()));install(data);lastSaved=JSON.stringify(project);status('Editable session opened.')}$('projectFile').onchange=async()=>{const file=$('projectFile').files[0];$('projectFile').value='';if(!file)return;try{await loadProject(file)}catch(e){status(e.message)}};

$('exportProject').onclick=()=>{dialog('Take your sound elsewhere','<p>WAV works in video editors, games and Worldbuilding’s Sound desk. MIDI carries editable notes to music software; it does not reproduce Jago’s sound design.</p><label>What to export<select id="exportKind"><option value="mix">Complete track · stereo WAV</option><option value="stems">Individual parts · WAV stem ZIP</option><option value="kit">Track + stems + editable project · ZIP</option><option value="midi">Editable musical notes · MIDI</option></select></label><div class="row"><label>Resolution<select id="exportRate"><option value="44100">44.1 kHz</option><option value="48000">48 kHz</option></select></label><label>Precision<select id="exportBits"><option value="16">16-bit</option><option value="24">24-bit</option></select></label><label>Ending<select id="exportEnding"><option value="loop" '+(project.loop?'selected':'')+'>Loop · wrap the reverb tail</option><option value="tail" '+(!project.loop?'selected':'')+'>Track · let the room fade out</option></select></label></div><button id="confirmExport" class="primary">Render & export</button><progress id="exportProgress" class="export-progress" max="1" value="0" hidden></progress><p id="exportStatus" class="hint">The project remains editable. Exports render locally; larger arrangements take longer.</p>');$('confirmExport').onclick=async()=>{if(exportBusy)return;const p=C.clone(project),kind=$('exportKind').value,rate=+$('exportRate').value,bits=+$('exportBits').value,loop=$('exportEnding').value==='loop';const budget=(C.seconds(p)+2)*rate*2*(bits/8)*(kind==='mix'?1:p.tracks.length+(kind==='kit'?1:0));if(kind!=='midi'&&budget>160000000){$('exportStatus').textContent='This export exceeds the 160 MB kit budget. Use fewer parts, a shorter session or 16-bit audio.';return}exportBusy=true;exportController=new AbortController;const signal=exportController.signal;$('confirmExport').disabled=true;$('exportProgress').hidden=false;try{if(kind==='midi'){F.save(F.midi(p),F.safe(p.name)+'.mid')}else{const files=[],jobs=(kind==='mix'?1:kind==='kit'?1:0)+(kind==='mix'?0:p.tracks.length);let done=0;const renderOne=async only=>{const buffer=await A.render(p,{sampleRate:rate,only,loop,signal,progress:v=>{if($('exportProgress'))$('exportProgress').value=(done+v)/Math.max(1,jobs)}});done++;return A.wav(buffer,bits)};if(kind==='mix'||kind==='kit'){const blob=await renderOne(null);if(signal.aborted)throw Error('Export cancelled');if(kind==='mix')F.save(blob,F.safe(p.name)+'.wav');else files.push({name:F.safe(p.name)+'.wav',blob})}if(kind!=='mix'){for(const t of p.tracks){if(signal.aborted)throw Error('Export cancelled');$('exportStatus').textContent='Rendering '+t.name+'…';files.push({name:'Stems/'+F.safe(t.name)+'-'+t.id.slice(0,8)+'.wav',blob:await renderOne(t.id)})}files.push({name:F.safe(p.name)+'.jagomusic',blob:new Blob([JSON.stringify(p,null,2)])},{name:'READ-ME.txt',blob:new Blob(['Created with Jago Music + SFX Studio. Built-in synthesis may be used in your projects, including commercial work, without attribution or fees. Imported audio retains its original rights. Stems are isolated renders; their sum can differ from the complete mix because of the master compressor. MIDI preserves notes, not these instrument timbres. No exclusive copyright or originality guarantee is made for seeded note sequences.'])});if(signal.aborted)throw Error('Export cancelled');F.save(await F.zip(files),F.safe(p.name)+'-audio-kit.zip')}}if(p.scoreSource)F.save(new Blob([p.notes],{type:'text/plain'}),F.safe(p.name)+'-source-rights.txt');status('Audio exported. Keep the editable project for future changes.');closeDialog()}catch(e){if($('exportStatus'))$('exportStatus').textContent=e.message;status(e.message)}finally{exportBusy=false;if($('confirmExport'))$('confirmExport').disabled=false}}};

$('examples').onclick=()=>{dialog('An idea to begin with','<div class="choice-grid">'+Object.entries(C.moods).map(([k,m])=>'<button data-example="'+k+'"><strong>'+m.name+'</strong><small>'+m.note+'</small></button>').join('')+'</div><p class="hint">Loads an editable example as one undoable change. Save separately to keep your current work.</p>');document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{change(()=>{project=C.generate({mood:b.dataset.example,seed:'jago-'+b.dataset.example});selected=project.tracks[0].id;sectionSelected=project.sections[1].id;selectedNote=null;playPosition=0});closeDialog();showView('music')})};

$('help').onclick=()=>{dialog('Jago Music + SFX · Help & about','<nav class="row"><button data-help="start">Getting started</button><button data-help="edit">Editing</button><button data-help="sounds">Sounds</button><button data-help="share">Exports & studios</button><button data-help="about">About & rights</button></nav><section id="helpContent"></section>');const pages={start:'<h3>Make music your way</h3><p>Create a complete song offers four generation approaches. Explore alternatives before choosing one; Shape section levels controls section volume.</p><h3>Start with a feeling</h3><p>Choose a mood, a seed and an amount of energy/activity. Generate unlocked parts creates a compatible arrangement from local musical rules. It is seeded composition, not a trained AI model or a recording of a performer. Play, then select a part, choose its instrument and adjust its level. Lock anything you want to keep before generating again.</p><p>Melody is the memorable tune, harmony supplies chords, foundation adds low notes, details add repeating accents and rhythm supplies the beat. Bars are short groups of four beats; sections are chapters of the track.</p>',edit:'<h3>Your notes, your arrangement</h3><p>Select a section block to edit its repeating pattern. The grid exposes compatible notes; existing outside-palette notes stay visible. Click to draw, drag to move, use the right edge to resize and Delete/right-click to remove. Vary notes changes just the selected pattern. Section menus rename, duplicate, reorder, resize and remove chapters.</p><p>Space plays/pauses. Ctrl Z and Ctrl Shift Z undo/redo; Ctrl S saves. Escape closes dialogs or cancels a note gesture. Your sliders use one undo per gesture. Undo is session history; save a .jagomusic file for a portable project.</p>',sounds:'<h3>Create from scratch</h3><p>Add tones, noise, impacts or recordings. Select an ingredient to edit timing and sound; draw volume and pitch curves. Invent sounds saves fresh recipes separately in My sounds. GUIDE.md has the steps.</p><h3>Make a useful sound</h3><p>Sound workshop offers 30 original procedural generators and a shelf of editable variations: nature beds, drones, walking sequences, door movement and short foley, fantasy/game/UI cues. Change the seed and character controls, then Listen. Save recipes to My sounds and favourite them. Add to arrangement creates an editable sound part; draw cues and resize their playback length.</p><p>Imported audio and sound cues have source offsets and fades, with grid position and length controlling placement. This version does not record microphones or load VST/SoundFont plugins.</p>',share:'<h3>Take it into your projects</h3><p>Export WAV mixes or ZIPs of isolated parts at 44.1/48 kHz and 16/24-bit. Loop exports fold release/reverb tails into the beginning. Track exports add a fading tail. MIDI exports the musical notes, not sound effects, recordings or Jago’s synthesis. Scores opens built-in editable passages or imports standard MIDI files. Each score displays its source rights; score exports include a source-rights note.</p><p>Import WAV into Worldbuilding’s Sound desk, your video editor or game engine. Use Send to studio to attach audio to any of the other six studios. Their Resources menu provides playback; exported images remain silent.</p>',about:'<h3>Open source. Free forever.</h3><p>Created by Cameron Jago Lis Illustrates. Local Windows and self-contained browser editions, with source under MIT. No account, subscription or online service required.</p><p>You may use exported built-in Jago synthesis in your own projects, including commercial work, without attribution or fees. Imported recordings keep their original rights. Seeds do not guarantee exclusive or legally unique compositions.</p><p><a href="https://cameronjagolis.co.uk/" target="_blank" rel="noopener">Creator website</a> · <a href="https://ko-fi.com/cameronillustrates" target="_blank" rel="noopener">Support the studios</a></p><p>Jago Sound 0.9.0. The included guide has more ways to make and share your work.</p>'};const show=k=>{$('helpContent').innerHTML=pages[k];document.querySelectorAll('[data-help]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.help===k))};document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>show(b.dataset.help));show('start')};

document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('saveProject').click();return}if(typing)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if($('dialog').open)return;if(e.code==='Space'){e.preventDefault();if(view==='music')$('play').click();else if(view==='sounds')$('soundPlay').click()}if(e.key==='Delete')deleteNote();if(e.key==='Escape'&&drag){project=drag.before;drag=null;render()}});

window.addEventListener('beforeunload',e=>{if(JSON.stringify(project)!==lastSaved){e.preventDefault();e.returnValue=''}});window.checkUnsaved=()=>JSON.stringify(project)!==lastSaved;

project.workshop=project.workshop||soundRecipe;soundRecipe=project.workshop;if(!recovered)lastSaved=JSON.stringify(project);const previousRender=render;render=function(){if(project.workshop)soundRecipe=project.workshop;previousRender();if(view==='sounds')renderSound()};

window.JagoMusic={getProject:()=>C.clone(project),install,loadProject,change,undo,redo,render,showView,dialog,closeDialog,Composer:C,Audio:A,Files:F,getCurrent:current,getPattern:pattern,getSelection:()=>({track:selected,section:sectionSelected,note:selectedNote}),select:(track,section)=>{selected=track;sectionSelected=section;selectedNote=null;render()},setSound:s=>{C.validateSound(s);soundChange(()=>soundRecipe=C.clone(s))},getSound:()=>C.clone(soundRecipe)};render();renderSound();window.appReady=true;if(recovered)status('Recovered your previous local session. Save a project backup when ready.');

