$('soundApply').onclick=()=>{const t=project.tracks.find(t=>t.id===editingSoundTrack);if(!t)return;change(()=>{t.sound=C.clone(soundRecipe);t.space=soundRecipe.space});status('Sound recipe updated on '+t.name+'.')};$('soundImport').onclick=()=>$('soundRecipeFile').click();$('soundRecipeFile').onchange=async()=>{const f=$('soundRecipeFile').files[0];$('soundRecipeFile').value='';if(!f)return;try{if(f.size>50000)throw Error('Choose a small .jagosound recipe.');const data=JSON.parse(await f.text());if(data.format!=='jagosound'||data.version!==1)throw Error('Choose a Jago sound recipe.');C.validateSound(data.recipe);editingSoundTrack=null;soundChange(()=>soundRecipe=C.clone(data.recipe));showView('sounds');status('Editable sound recipe opened.')}catch(e){status(e.message)}};

$('soundExport').onclick=()=>{const s=C.clone(soundRecipe);dialog('Export your sound','<label>Format<select id="soundExportKind"><option value="wav">Stereo WAV · 44.1 kHz, 16-bit</option><option value="recipe">Editable .jagosound recipe</option><option value="both">WAV + recipe ZIP</option></select></label><button id="soundExportConfirm" class="primary">Export sound</button><p class="hint" id="soundExportStatus">WAV works in sound desks, games and video. Recipes reopen here.</p>');$('soundExportConfirm').onclick=async()=>{const kind=$('soundExportKind').value;$('soundExportConfirm').disabled=true;try{const name=F.safe(s.label||(s.characterName||C.soundTypes[s.type].name)+' - '+s.seed.slice(0,6)),recipe=new Blob([JSON.stringify({format:'jagosound',version:1,recipe:s},null,2)],{type:'application/json'});if(kind==='recipe')F.save(recipe,name+'.jagosound');else{const b=await A.renderSound(s),wav=A.wav(b);if(kind==='both')F.save(await F.zip([{name:name+'.wav',blob:wav},{name:name+'.jagosound',blob:recipe}]),name+'-sound.zip');else F.save(wav,name+'.wav')}status('Sound exported.');closeDialog()}catch(e){$('soundExportStatus').textContent=e.message;$('soundExportConfirm').disabled=false}}};



document.querySelectorAll("[data-character]").forEach(b=>b.onclick=()=>soundChange(()=>{const values={gentle:{size:.25,tone:.4,texture:.2,rate:.2},balanced:{size:.5,tone:.55,texture:.45,rate:.5},bold:{size:.85,tone:.65,texture:.75,rate:.85}}[b.dataset.character];Object.assign(soundRecipe,values)}));



$('manualAdd').onclick=()=>$('addTrack').click();$('applyLength').onclick=()=>change(()=>{const target=C.clamp(+$('targetLength').value||45,5,180),bars=Math.min(Math.floor(180*project.tempo/240),Math.max(project.sections.length,Math.round(target*project.tempo/240))),needed=Math.max(project.sections.length,Math.ceil(bars/16));while(project.sections.length<needed){const source=project.sections[Math.min(1,project.sections.length-1)],s={id:C.id(),name:'Development '+(project.sections.length+1),bars:4,energy:1};project.sections.push(s);for(const t of project.tracks){t.patterns[s.id]=C.clone(t.patterns[source.id]||{bars:4,notes:[]});t.enabled[s.id]=t.enabled[source.id]!==false}}const base=Math.floor(bars/project.sections.length),extra=bars%project.sections.length;project.sections.forEach((s,i)=>s.bars=base+(i<extra?1:0));playPosition=Math.min(playPosition,C.seconds(project)-.01);status('Length fitted to whole bars. Notes retained; additional sections added if needed.')});$('trackShape').onchange=()=>change(()=>{project.loop=$('trackShape').value==='loop';status('Playback shape changed. Generate to write a looping return or resolving ending.')} ,{keepPlaying:A.playing,liveArrangement:A.playing});for(const [id,key]of [['trackFadeIn','fadeIn'],['trackFadeOut','fadeOut']])$(id).onchange=()=>change(()=>project[key]=C.clamp(+$(id).value,0,10),{keepPlaying:A.playing,liveArrangement:A.playing});



async function drawCueWave(t){const canvas=$('cueWave');try{const b=await A.source(t);if(!canvas.isConnected||current()?.id!==t.id||!b)return;const d=b.getChannelData(0),g=canvas.getContext('2d'),w=canvas.width,h=canvas.height,style=getComputedStyle(document.documentElement);g.fillStyle=style.getPropertyValue('--stage');g.fillRect(0,0,w,h);g.strokeStyle=style.getPropertyValue('--accent');g.beginPath();for(let x=0;x<w;x++){let max=0;const from=Math.floor(x*d.length/w),to=Math.max(from+1,Math.floor((x+1)*d.length/w));for(let i=from;i<to;i++)max=Math.max(max,Math.abs(d[i]));g.moveTo(x,h/2-max*h*.8);g.lineTo(x,h/2+max*h*.8)}g.stroke();const offset=t.cue?.offset||0,clip=(pattern()?.notes.find(n=>n.id===selectedNote)||pattern()?.notes[0])?.length*(60/project.tempo/4)||b.duration;g.fillStyle=style.getPropertyValue('--accentSoft');g.globalAlpha=.55;g.fillRect(0,0,offset/b.duration*w,h);g.fillRect(Math.min(w,(offset+clip)/b.duration*w),0,w,h);g.globalAlpha=1;g.strokeStyle=style.getPropertyValue('--gold');g.beginPath();g.moveTo(offset/b.duration*w,0);g.lineTo(offset/b.duration*w,h);g.stroke();canvas.onclick=e=>{const rect=canvas.getBoundingClientRect();$('cueOffset').value=Math.min(b.duration-.01,Math.max(0,(e.clientX-rect.left)/rect.width*b.duration)).toFixed(2);$('cueOffset').onchange()}}catch(e){status('Waveform unavailable: '+e.message)}}



let soundUpdateTimer;function queueSoundPreview(){if(!A.soundPlaying)return;clearTimeout(soundUpdateTimer);soundUpdateTimer=setTimeout(async()=>{const b=await A.updateSound(C.clone(soundRecipe));if(b){soundBuffer=b;waveform(b)}},120)}



